Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";function Die([string]$Code,[string]$Detail){throw($Code+":"+$Detail)};$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path;foreach($f in @((Join-Path $RepoRoot "scripts\storage\ld_backup_set_seal_v1.ps1"),(Join-Path $RepoRoot "scripts\storage\ld_backup_set_verify_v1.ps1"),(Join-Path $RepoRoot "scripts\selftest\_selftest_ld_backup_set_seal_v1.ps1"))){if(-not(Test-Path -LiteralPath $f -PathType Leaf)){Die "FILE_MISSING" $f};$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($f,[ref]$t,[ref]$e);if(@($e).Count){Die "PARSE_FAIL" ($f+":"+$e[0].Message)};Write-Output("PARSE_OK: "+$f)};foreach($s in @("ld.backup.set.seal.v1.json","ld.backup.set.seal.receipt.v1.json","ld.backup.set.verify.receipt.v1.json")){if(-not(Test-Path -LiteralPath (Join-Path $RepoRoot ("schemas\"+$s)) -PathType Leaf)){Die "SCHEMA_MISSING" $s}};Write-Output "SCHEMAS_OK";$self=Join-Path $RepoRoot "scripts\selftest\_selftest_ld_backup_set_seal_v1.ps1";$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $self -RepoRoot $RepoRoot;if($LASTEXITCODE-ne0){Die "SELFTEST_EXIT" ([string]$LASTEXITCODE)};$text=$out-join"`n";Write-Output $text;if($text-notmatch"SELFTEST_LD_BACKUP_SET_SEAL_OK"){Die "TOKEN_MISSING" ""};Write-Output "LEGACY_DOCTOR_BACKUP_SET_SEAL_GREEN"
